package solution

import (
	"errors"
	"reflect"
	"testing"
)

func TestRunPlanEmptyAndNilExecute(t *testing.T) {
	outcomes, err := RunPlan(nil, func(string) error { return nil })
	if err != nil {
		t.Fatalf("empty plan returned error: %v", err)
	}
	if outcomes == nil || len(outcomes) != 0 {
		t.Fatalf("empty plan outcomes = %#v, want non-nil empty slice", outcomes)
	}

	called := false
	if _, err := RunPlan(nil, nil); err == nil {
		t.Fatal("nil execute was accepted")
	}
	if called {
		t.Fatal("unexpected callback invocation")
	}
}

func TestRunPlanDeterministicDependencyOrder(t *testing.T) {
	steps := []Step{
		{Name: "publish", Requires: []string{"compile", "check"}},
		{Name: "check"},
		{Name: "compile", Requires: []string{"fetch"}},
		{Name: "fetch"},
		{Name: "notify", Requires: []string{"publish"}},
	}
	original := cloneStepsForTest(steps)
	var calls []string
	outcomes, err := RunPlan(steps, func(name string) error {
		calls = append(calls, name)
		return nil
	})
	if err != nil {
		t.Fatalf("RunPlan returned error: %v", err)
	}
	wantCalls := []string{"check", "fetch", "compile", "publish", "notify"}
	if !reflect.DeepEqual(calls, wantCalls) {
		t.Fatalf("execution order = %v, want %v", calls, wantCalls)
	}
	wantOutcomes := make([]StepOutcome, len(wantCalls))
	for i, name := range wantCalls {
		wantOutcomes[i] = StepOutcome{Name: name, Status: "succeeded"}
	}
	if !reflect.DeepEqual(outcomes, wantOutcomes) {
		t.Fatalf("outcomes = %#v, want %#v", outcomes, wantOutcomes)
	}
	if !reflect.DeepEqual(steps, original) {
		t.Fatalf("RunPlan mutated steps: got %#v, want %#v", steps, original)
	}
}

func TestRunPlanFailureSkipsDependentsAndContinues(t *testing.T) {
	boom := errors.New("execution exploded")
	steps := []Step{
		{Name: "independent-first"},
		{Name: "fails"},
		{Name: "direct", Requires: []string{"fails"}},
		{Name: "transitive", Requires: []string{"direct"}},
		{Name: "independent-last"},
	}
	var calls []string
	outcomes, err := RunPlan(steps, func(name string) error {
		calls = append(calls, name)
		if name == "fails" {
			return boom
		}
		return nil
	})
	if err != nil {
		t.Fatalf("callback failure became RunPlan error: %v", err)
	}
	wantCalls := []string{"independent-first", "fails", "independent-last"}
	if !reflect.DeepEqual(calls, wantCalls) {
		t.Fatalf("calls = %v, want %v", calls, wantCalls)
	}
	want := []StepOutcome{
		{Name: "independent-first", Status: "succeeded"},
		{Name: "fails", Status: "failed", Error: boom.Error()},
		{Name: "direct", Status: "skipped"},
		{Name: "transitive", Status: "skipped"},
		{Name: "independent-last", Status: "succeeded"},
	}
	if !reflect.DeepEqual(outcomes, want) {
		t.Fatalf("outcomes = %#v, want %#v", outcomes, want)
	}
}

func TestRunPlanRejectsMalformedStructuresBeforeExecution(t *testing.T) {
	tests := []struct {
		name  string
		steps []Step
	}{
		{"empty step name", []Step{{Name: ""}}},
		{"leading step whitespace", []Step{{Name: " task"}}},
		{"trailing step whitespace", []Step{{Name: "task\t"}}},
		{"duplicate step", []Step{{Name: "a"}, {Name: "a"}}},
		{"empty dependency", []Step{{Name: "a", Requires: []string{""}}}},
		{"dependency whitespace", []Step{{Name: "a", Requires: []string{" b"}}, {Name: "b"}}},
		{"duplicate dependency", []Step{{Name: "a", Requires: []string{"b", "b"}}, {Name: "b"}}},
		{"unknown dependency", []Step{{Name: "a", Requires: []string{"missing"}}}},
		{"self dependency", []Step{{Name: "a", Requires: []string{"a"}}}},
		{"two node cycle", []Step{{Name: "a", Requires: []string{"b"}}, {Name: "b", Requires: []string{"a"}}}},
		{"longer cycle", []Step{{Name: "a", Requires: []string{"b"}}, {Name: "b", Requires: []string{"c"}}, {Name: "c", Requires: []string{"a"}}}},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			original := cloneStepsForTest(tc.steps)
			calls := 0
			outcomes, err := RunPlan(tc.steps, func(string) error {
				calls++
				return nil
			})
			if err == nil {
				t.Fatalf("RunPlan accepted malformed plan; outcomes = %#v", outcomes)
			}
			if calls != 0 {
				t.Fatalf("execute called %d times before structural validation completed", calls)
			}
			if !reflect.DeepEqual(tc.steps, original) {
				t.Fatalf("malformed plan was mutated: got %#v, want %#v", tc.steps, original)
			}
		})
	}
}

func TestRunPlanValidatesEntirePlanBeforeExecuting(t *testing.T) {
	steps := []Step{{Name: "valid"}, {Name: "broken", Requires: []string{"unknown"}}}
	calls := 0
	if _, err := RunPlan(steps, func(string) error {
		calls++
		return nil
	}); err == nil {
		t.Fatal("expected structural validation error")
	}
	if calls != 0 {
		t.Fatalf("execute called %d times despite later structural error", calls)
	}
}

func cloneStepsForTest(steps []Step) []Step {
	copySteps := make([]Step, len(steps))
	for i, step := range steps {
		copySteps[i] = step
		if step.Requires != nil {
			copySteps[i].Requires = append([]string(nil), step.Requires...)
		}
	}
	return copySteps
}

package solution

import (
	"reflect"
	"testing"
)

func TestReviewNewlyReadyEarlierStepWins(t *testing.T) {
	var calls []string
	_, err := RunPlan([]Step{{Name: "a", Requires: []string{"b"}}, {Name: "b"}, {Name: "c"}}, func(n string) error {
		calls = append(calls, n)
		return nil
	})
	if err != nil || !reflect.DeepEqual(calls, []string{"b", "a", "c"}) {
		t.Fatalf("ready steps must use input-order priority: calls=%v err=%v", calls, err)
	}
}

